    for f in fs:
        if f.endswith('.lean'): ondisk.add(os.path.join(dp,f))
ondisk.add('AlgebraicJacobian.lean')
# reachable set (import closure from root)
name2path={p[:-5].replace('/','.'):p for p in ondisk}
imports={}
for n,p in name2path.items():
    ims=[]
    for line in open(p,encoding='utf-8',errors='replace'):
        m=re.match(r'^import\s+([\w.]+)',line)
        if m: ims.append(m.group(1))
    imports[n]=ims
seen=set(); stack=['AlgebraicJacobian']
while stack:
    x=stack.pop()
    if x in seen: continue
    seen.add(x)
    for i in imports.get(x,[]):
        if i in name2path and i not in seen: stack.append(i)
reachable={name2path[n] for n in seen}
notondisk=0; unrootedn=0; ok_notondisk=0; ok_unrooted=0
for n in glob.glob('hgraph/nodes/*.md'):
    head=open(n,encoding='utf-8',errors='replace').read(1200)
    m=re.search(r'^file:\s*(\S+)', head, re.M)
    if not m: continue
    f=m.group(1); st=re.search(r'^lean_status:\s*(\S+)', head, re.M)
    ok = st and st.group(1)=='lean_ok'
    if f not in ondisk:
        notondisk+=1; ok_notondisk += 1 if ok else 0
    elif f not in reachable:
        unrootedn+=1; ok_unrooted += 1 if ok else 0
print('nodes whose file is NOT ON DISK:', notondisk, '(lean_ok:',ok_notondisk,')')
print('nodes whose file is on disk but UNROOTED:', unrootedn, '(lean_ok:',ok_unrooted,')')
